@classmethod
@functools.lru_cache()
def get_full_name(cls) -> str:
    """Get the full name of the state.

    Returns:
        The full name of the state.
    """
    name = cls.get_name()
    parent_state = cls.get_parent_state()
    if parent_state is not None:
        name = ".".join((parent_state.get_full_name(), name))
    return name

